fn tangent(r: Vec<u64>, x: Vec<u64>) -> bool {
    // Since `x` is sorted in non‐decreasing order, we can binary‐search into it.
    // We simply iterate over all elements in `r` and check if any of them
    // appear in `x`. If so, we immediately return true. Otherwise, false.
    for value in r {
        if x.binary_search(&value).is_ok() {
            return true;
        }
    }
    false
}

